let nextId = 1;
function buildRequest(method, params) {
  return { jsonrpc: "2.0", id: nextId++, method, params };
}

function validateArgs(inputSchema, arguments_) {
  for (const required of inputSchema.required || []) {
    if (!(required in arguments_)) {
      throw new Error(`Missing required argument: ${required}`);
    }
  }
}

// Request, id present, reply expected
{ "jsonrpc": "2.0", "id": 10, "method": "tools/call", "params": { "name": "ping_tool", "arguments": {} } }

// Notification, no id, no reply expected
{ "jsonrpc": "2.0", "method": "notifications/progress", "params": { "progressToken": "t1", "progress": 50 } }

// Step 1: choose the method
const method = "tools/call";

// Step 2: build params, remembering name + arguments
const params = {
  name: "translate_text",
  arguments: { text: "Good morning", target_language: "fr" }
};

// Step 3: assign the next id and assemble the envelope
const request = { jsonrpc: "2.0", id: nextId++, method, params };

console.log(JSON.stringify(request));
